declare const Editor: {
  App?: { version: string };
  Project: { path: string };
  Message: { request(channel: string, message: string, ...args: unknown[]): Promise<unknown> };
};

type SceneExecutor = <T>(method: string, argument?: unknown) => Promise<T>;
type RawAsset = {
  name?: string;
  url?: string;
  source?: string;
  path?: string;
  file?: string;
  uuid?: string;
  type?: string;
  imported?: boolean;
  subAssets?: Record<string, RawAsset> | RawAsset[];
};

const ALLOWED_EXTENSIONS = new Set([".png", ".jpg", ".jpeg", ".webp", ".mp3", ".wav", ".ogg", ".ttf", ".otf"]);
const MAX_ASSET_BYTES = 25 * 1024 * 1024;
const MAX_SCRIPT_BYTES = 512 * 1024;

function sha256(content: Buffer | string): string {
  return createHash("sha256").update(content).digest("hex");
}

function sceneFileId(): string {
  const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
  let value = "";
  for (let index = 0; index < 22; index += 1) {
    value += alphabet[Math.floor(Math.random() * alphabet.length)];
  }
  return value;
}

