function normalizeAsset(raw: RawAsset): AssetInfo {
  const subAssets = raw.subAssets
    ? Object.values(raw.subAssets).map(normalizeAsset)
    : undefined;
  return {
    url: raw.url ?? raw.source ?? "",
    uuid: raw.uuid ?? "",
    ...(raw.path ? { path: raw.path } : {}),
    ...(raw.name ? { name: raw.name } : {}),
    ...(raw.type ? { type: raw.type } : {}),
    ...(raw.imported === undefined ? {} : { imported: raw.imported }),
    ...(subAssets?.length ? { subAssets } : {}),
  };
}

async function withHash(raw: RawAsset | null): Promise<AssetInfo | null> {
  if (!raw) return null;
  const info = normalizeAsset(raw);
  if (raw.file) {
    try {
      info.hash = sha256(await readFile(raw.file));
    } catch {
      delete info.hash;
    }
  }
  return info;
}

export class CreatorP2Adapter implements P2Adapter {
  private prefabContext: PrefabContext | undefined;
  private compileLogOffset = 0;

  constructor(
    private readonly executeScene: SceneExecutor,
    private readonly getSceneTree: () => Promise<SceneSnapshot>,
    private readonly saveScene: () => Promise<void>,
    private readonly getPreviewStatus?: () => Promise<PreviewStatus>,
  ) {}

  private async ensureSceneSwitchSafe(): Promise<void> {
    const dirty = await Editor.Message.request("scene", "query-dirty");
    if (dirty !== false) {
      throw new BridgeFault(
        dirty === true ? "REVISION_CONFLICT" : "INTERNAL_ERROR",
        dirty === true ? "Current scene has unsaved changes. Save or discard them before opening or creating another scene"
          : "Current scene unsaved state is unknown; document switching is blocked",
      );
    }
  }

  async sceneOpen(url: string): Promise<SceneSnapshot> {
    const deadline = Date.now() + 15_000;
    let asset: AssetInfo | null | undefined;
    while (!asset && Date.now() < deadline) {
      asset = await this.assetGetInfo(url) ?? (await this.assetList()).find((item) => item.url === url);
      if (!asset) await new Promise((resolve) => setTimeout(resolve, 200));
    }
    if (!asset) throw new BridgeFault("NOT_FOUND", `${url} was not found`);
    if (asset.url !== url || typeof asset.uuid !== "string" || !asset.uuid.trim())
      throw new BridgeFault("INVALID_REQUEST", "Requested scene asset identity is incomplete or mismatched");
    await this.ensureSceneSwitchSafe();
    this.prefabContext = undefined;
    let phase = "open-scene";
    try {
      await Editor.Message.request("scene", "open-scene", asset.uuid);
      phase = "observe-target";
      return await this.waitDocumentOpen(asset);
    } catch (error) { this.sceneEffectUnknown(error, url, phase); }
  }

  async sceneList(): Promise<SceneListItem[]> {
    const raw = await Editor.Message.request("asset-db", "query-assets", {
      pattern: "db://assets/**/*.scene",
    }) as RawAsset[];
    const scenes = (raw?.length ? raw : await this.assetList())
      .filter((item) => (item.url ?? "").endsWith(".scene"))
      .map(normalizeAsset);
    return scenes.map((item) => ({
      url: item.url,
      uuid: item.uuid,
      ...(item.name ? { name: item.name } : {}),
    }));
  }

  async sceneCreate(url: string): Promise<SceneSnapshot> {
    if (!url.startsWith("db://assets/") || !url.endsWith(".scene")) {
      throw new BridgeFault("INVALID_REQUEST", "Scene URL must be under db://assets/ and end with .scene");
    }
    if (await this.assetGetInfo(url)) {
      throw new BridgeFault("ALREADY_EXISTS", `${url} already exists`);
    }
    await this.ensureSceneSwitchSafe();
    // Parent creation can already have effects; failures after this point cannot prove no write occurred.
    let phase = "ensure-asset-parents";
    try {
      await this.ensureAssetParents(url);
      const name = url.split("/").pop()!.replace(/\.scene$/i, "") || "NewScene";
      phase = "create-asset";
      const raw = await Editor.Message.request(
        "asset-db", "create-asset", url, emptySceneContent(name), { overwrite: false },
      ) as RawAsset | null;
      if (!raw) throw new BridgeFault("INTERNAL_ERROR", "Creator did not create the scene asset");
      phase = "refresh-asset";
      await Editor.Message.request("asset-db", "refresh-asset", url);
      phase = "open-target";
      return await this.sceneOpen(url);
    } catch (error) { this.sceneEffectUnknown(error, url, phase); }
  }

  async sceneSave(): Promise<SceneSnapshot> {
    await this.saveScene();
    return this.getSceneTree();
  }

  async sceneValidate(url?: string): Promise<SceneValidateResult> {
    if (url) await this.sceneOpen(url);
    const tree = await this.getSceneTree();
    const consoleErrors = await this.scriptGetErrors();
    const reopenable = url
      ? Boolean(await this.assetGetInfo(url))
      : tree.sceneUrl.startsWith("db://")
        ? Boolean(await this.assetGetInfo(tree.sceneUrl))
        : true;

    try {
      const live = await this.executeScene<SceneValidateResult>("sceneValidate");
      return validateScene(
        { sceneUrl: live.sceneUrl || tree.sceneUrl, revision: live.revision || tree.revision, roots: tree.roots },
        {
          isComponentRegistered: (className) => !live.issues.some(
            (issue) => issue.code === "COMPONENT_NOT_REGISTERED"
              && issue.message === `Component ${className} is not registered`,
          ),
          consoleErrors,
          reopenable: reopenable && live.checks.reopenable,
        },
      );
    } catch {
      const available = new Set(await this.componentListAvailable());
      return validateScene(tree, {
        isComponentRegistered: (className) => available.has(className),
        consoleErrors,
        reopenable,
      });
    }
  }

  private async ensureAssetParents(url: string): Promise<void> {
    const parts = url.slice("db://assets/".length).split("/").slice(0, -1);
    let current = "db://assets";
    for (const part of parts) {
      current += `/${part}`;
      if (!await this.assetGetInfo(current)) {
        await Editor.Message.request("asset-db", "create-asset", current, null, { overwrite: false });
      }
    }
  }

  private async ensureImageSpriteFrame(url: string, uuid: string): Promise<void> {
    if (![".png", ".jpg", ".jpeg", ".webp"].includes(extname(url).toLowerCase())) return;
    const rawMeta = await Editor.Message.request("asset-db", "query-asset-meta", uuid) as string | {
      userData?: Record<string, unknown>;
    } | null;
    if (!rawMeta) return;
    const meta = typeof rawMeta === "string" ? JSON.parse(rawMeta) as { userData?: Record<string, unknown> } : rawMeta;
    meta.userData ??= {};
    if (meta.userData.type === "sprite-frame") return;
    meta.userData.type = "sprite-frame";
    await Editor.Message.request("asset-db", "save-asset-meta", uuid, JSON.stringify(meta));
    await Editor.Message.request("asset-db", "refresh-asset", url);
  }

  async assetList(query?: string): Promise<AssetInfo[]> {
    const raw = await Editor.Message.request("asset-db", "query-assets", { pattern: "db://assets/**" }) as RawAsset[];
    const needle = query?.toLowerCase();
    return raw
      .filter((item) => !needle || `${item.url ?? ""} ${item.name ?? ""}`.toLowerCase().includes(needle))
      .map(normalizeAsset);
  }

  async assetGetInfo(urlOrUuid: string): Promise<AssetInfo | null> {
    const raw = await Editor.Message.request("asset-db", "query-asset-info", urlOrUuid) as RawAsset | null;
    return withHash(raw);
  }

  async assetImport(request: AssetImportRequest): Promise<AssetInfo> {
    if (!isAbsolute(request.sourcePath)) throw new BridgeFault("INVALID_REQUEST", "sourcePath must be absolute");
    const sourceStat = await stat(request.sourcePath).catch(() => null);
    if (!sourceStat?.isFile()) throw new BridgeFault("NOT_FOUND", "sourcePath must reference one regular file");
    if (sourceStat.size > MAX_ASSET_BYTES) throw new BridgeFault("INVALID_REQUEST", "Asset exceeds 25 MB");
    if (!ALLOWED_EXTENSIONS.has(extname(request.sourcePath).toLowerCase())) {
      throw new BridgeFault("INVALID_REQUEST", "Unsupported asset extension");
    }
    if (!request.destinationUrl.startsWith("db://assets/")) {
      throw new BridgeFault("INVALID_REQUEST", "destinationUrl must be under db://assets/");
    }
    if (extname(request.destinationUrl).toLowerCase() !== extname(request.sourcePath).toLowerCase()) {
      throw new BridgeFault("INVALID_REQUEST", "Source and destination extensions must match");
    }
    if (await this.assetGetInfo(request.destinationUrl)) {
      throw new BridgeFault("ALREADY_EXISTS", `${request.destinationUrl} already exists`);
    }
    await this.ensureAssetParents(request.destinationUrl);
    const raw = await Editor.Message.request(
      "asset-db",
      "import-asset",
      request.sourcePath,
      request.destinationUrl,
      { overwrite: false, rename: false },
    ) as RawAsset | null;
    if (!raw) throw new BridgeFault("INTERNAL_ERROR", "Creator did not import the asset");
    if (raw.uuid) await this.ensureImageSpriteFrame(request.destinationUrl, raw.uuid);
    return (await this.assetGetInfo(request.destinationUrl)) ?? (await withHash(raw))!;
  }

  async assetRefresh(url: string): Promise<AssetInfo | null> {
    await Editor.Message.request("asset-db", "refresh-asset", url);
    const info = await this.assetGetInfo(url);
    if (info?.uuid) await this.ensureImageSpriteFrame(url, info.uuid);
    return this.assetGetInfo(url);
  }

  async assetResolveReference(reference: AssetReference): Promise<AssetInfo> {
    const root = await this.assetGetInfo(reference.url);
    if (!root) throw new BridgeFault("NOT_FOUND", `${reference.url} was not found`);
    if (!reference.subAsset) return root;
    const direct = await this.assetGetInfo(`${reference.url}/${reference.subAsset}`);
    const nested = root.subAssets?.find((item) => item.name === reference.subAsset || item.url.endsWith(`/${reference.subAsset}`));
    const result = direct ?? nested;
    if (!result) throw new BridgeFault("NOT_FOUND", `Sub asset ${reference.subAsset} was not found`);
    return result;
  }

  async assetDelete(request: AssetDeleteRequest): Promise<{ url: string; deleted: true; previousUuid: string; previousHash: string }> {
    const current = await this.assetGetInfo(request.url);
    if (!current) throw new BridgeFault("NOT_FOUND", `${request.url} was not found`);
    if (!current.hash) throw new BridgeFault("INVALID_REQUEST", "Only ordinary files with a readable hash can be deleted");
    if (current.hash !== request.expectedHash) {
      throw new BridgeFault("HASH_CONFLICT", `Expected ${request.expectedHash}, current hash is ${current.hash}`);
    }
    if (request.confirmation !== `DELETE_ASSET:${request.url}`) {
      throw new BridgeFault("INVALID_REQUEST", `confirmation must equal DELETE_ASSET:${request.url}`);
    }
    await Editor.Message.request("asset-db", "delete-asset", request.url);
    if (await this.assetGetInfo(request.url)) throw new BridgeFault("INTERNAL_ERROR", `${request.url} still exists after deletion`);
    return { url: request.url, deleted: true, previousUuid: current.uuid, previousHash: current.hash };
  }

  assetInspectDependencies(urlOrUuid: string, depth?: number): Promise<AssetDependencyGraph> {
    return inspectAssetDependencies(urlOrUuid, depth);
  }

  assetValidateDependencies(urlOrUuid: string, depth?: number): Promise<AssetDependencyGraph> {
    return validateAssetDependencies(urlOrUuid, depth);
  }

  editorGetSelection(): Promise<EditorSelection> {
    return getEditorSelection();
  }

  editorSetSelection(selection: { nodeUuids?: string[]; assetUuids?: string[] }): Promise<EditorSelection> {
    return setEditorSelection(selection);
  }

  editorPerformanceSnapshot(): Promise<PerformanceSnapshot> {
    return buildPerformanceSnapshot(() => this.getSceneTree());
  }

  async editorRuntimeState(): Promise<RuntimeState> {
    const preview = this.getPreviewStatus
      ? await this.getPreviewStatus()
      : { available: false, running: false, stopSupported: false, message: "Preview adapter not wired" };
    return buildRuntimeState(preview);
  }

  /**
   * Runs code in the scene-script process.
   * Confirm string `EXECUTE_SCENE_SCRIPT` is enforced by bridge-service.
   */
  scriptExecuteScene(request: ExecuteScriptRequest): Promise<ExecuteScriptResult> {
    return this.executeScene<ExecuteScriptResult>("runUserScript", {
      code: request.code,
      timeoutMs: request.timeoutMs,
    });
  }

  /**
   * Runs code in the editor extension process.
   * Confirm string `EXECUTE_EDITOR_SCRIPT` is enforced by bridge-service.
   */
  scriptExecuteEditor(request: ExecuteScriptRequest): Promise<ExecuteScriptResult> {
    return runEditorUserScript(request.code, request.timeoutMs);
  }

  async scriptWrite(request: ScriptWriteRequest): Promise<AssetInfo> {
    if (!request.url.startsWith("db://assets/") || !request.url.endsWith(".ts")) {
      throw new BridgeFault("INVALID_REQUEST", "Scripts must be .ts assets under db://assets/");
    }
    if (Buffer.byteLength(request.content) > MAX_SCRIPT_BYTES) {
      throw new BridgeFault("INVALID_REQUEST", "Script exceeds 512 KB");
    }
    const current = await this.assetGetInfo(request.url);
    if (!current && request.expectedHash !== null) throw new BridgeFault("HASH_CONFLICT", "Script does not exist");
    if (current && request.expectedHash === null) throw new BridgeFault("ALREADY_EXISTS", `${request.url} already exists`);
    if (current?.hash && current.hash !== request.expectedHash) {
      throw new BridgeFault("HASH_CONFLICT", `Expected ${request.expectedHash}, current hash is ${current.hash}`);
    }
    await this.ensureAssetParents(request.url);
    this.compileLogOffset = (await stat(this.projectLogPath()).catch(() => null))?.size ?? 0;
    const raw = current
      ? await Editor.Message.request("asset-db", "save-asset", request.url, request.content) as RawAsset | null
      : await Editor.Message.request("asset-db", "create-asset", request.url, request.content, { overwrite: false }) as RawAsset | null;
    if (!raw) throw new BridgeFault("INTERNAL_ERROR", "Creator did not save the script");
    await Editor.Message.request("asset-db", "refresh-asset", request.url);
    return (await this.assetGetInfo(request.url)) ?? normalizeAsset(raw);
  }

  async scriptWaitCompile(request: CompileRequest): Promise<CompileResult> {
    const timeoutMs = request.timeoutMs ?? 30_000;
    const deadline = Date.now() + timeoutMs;
    while (Date.now() < deadline) {
      const sceneReady = await Editor.Message.request("scene", "query-is-ready") as boolean;
      const info = await this.assetGetInfo(request.url);
      const registered = request.className ? await this.scriptFindComponent(request.className) : undefined;
      if (sceneReady && info?.imported && (registered ?? true)) {
        return {
          status: "compiled",
          imported: true,
          ...(registered === undefined ? {} : { componentRegistered: registered }),
          errors: [],
        };
      }
      const errors = await this.readCompileErrors();
      if (errors.length) return { status: "failed", imported: Boolean(info?.imported), errors };
      await new Promise((resolve) => setTimeout(resolve, 250));
    }
    return {
      status: "timeout",
      imported: Boolean((await this.assetGetInfo(request.url))?.imported),
      ...(request.className ? { componentRegistered: await this.scriptFindComponent(request.className) } : {}),
      errors: await this.readCompileErrors(),
    };
  }

  async scriptGetErrors(since?: string): Promise<string[]> {
    const content = await readFile(this.projectLogPath(), "utf8").catch(() => "");
    const threshold = since ? Date.parse(since) : 0;
    return content.split(/\r?\n/).filter((line) => {
      if (!/(error|exception|failed|typescript)/i.test(line)) return false;
      const match = /^(\d{1,2})-(\d{1,2})-(\d{4}) (\d{2}):(\d{2}):(\d{2})/.exec(line);
      const timestamp = match
        ? new Date(Number(match[3]), Number(match[1]) - 1, Number(match[2]), Number(match[4]), Number(match[5]), Number(match[6])).getTime()
        : Number.NaN;
      return !Number.isFinite(timestamp) || timestamp >= threshold;
    }).slice(-100);
  }

  private projectLogPath(): string {
    return join(Editor.Project.path, "temp", "logs", "project.log");
  }

  private async readCompileErrors(): Promise<string[]> {
    const content = await readFile(this.projectLogPath()).catch(() => Buffer.alloc(0));
    return content.subarray(Math.min(this.compileLogOffset, content.length))
      .toString("utf8")
      .split(/\r?\n/)
      .filter((line) => /(error|exception|failed|typescript)/i.test(line))
      .slice(-100);
  }

  async scriptFindComponent(className: string): Promise<boolean> {
    const components = await this.componentListAvailable();
    return components.includes(className);
  }

  async componentListAvailable(): Promise<string[]> {
    const engine = await Editor.Message.request("scene", "query-classes", { extends: "cc.Component" }) as Array<{ name: string }>;
    const project = await Editor.Message.request("scene", "query-components") as Array<{ name: string }>;
    return [...new Set([...engine.map((item) => item.name), ...project.map((item) => item.name)])].sort();
  }

  componentGetSchema(name: string): Promise<ComponentSchema> {
    return this.executeScene<ComponentSchema>("getComponentSchema", name);
  }

  debugSceneLogs(filter?: { level?: string; since?: string; query?: string; limit?: number }): Promise<JsonValue> {
    return this.executeScene<JsonValue>("getConsoleLogs", filter ?? {});
  }

  prefabProbe(): Promise<JsonValue> {
    return this.executeScene<JsonValue>("prefabProbe");
  }

  async prefabCreate(request: PrefabCreateRequest): Promise<AssetInfo> {
    if (await this.assetGetInfo(request.url)) throw new BridgeFault("ALREADY_EXISTS", `${request.url} already exists`);
    const result = await this.executeScene<{ uuid?: string; url: string }>("prefabCreate", request);
    await Editor.Message.request("asset-db", "refresh-asset", request.url);
    const info = await this.assetGetInfo(result.uuid ?? request.url);
    if (!info) throw new BridgeFault("INTERNAL_ERROR", "Prefab was not registered in AssetDB");
    return info;
  }

  async prefabOpen(url: string): Promise<PrefabContext> {
    const previousContext = this.prefabContext;
    this.prefabContext = undefined;
    const asset = await this.assetGetInfo(url);
    if (!asset) throw new BridgeFault("NOT_FOUND", `${url} was not found`);
    if (!asset.uuid.trim() || asset.url !== url) throw new BridgeFault("INTERNAL_ERROR", "Requested Prefab asset identity is incomplete or mismatched");
    if (Editor.App?.version !== "3.8.8") throw new BridgeFault("UNSUPPORTED", "Verified Prefab identity queries require Creator 3.8.8");
    const previous = await this.getSceneTree();
    const alreadyOpen = await this.readTargetPrefab(asset);
    const previousSceneUrl = alreadyOpen && previousContext?.prefabUrl === url ? previousContext.previousSceneUrl
      : previous.sceneUrl.endsWith(".scene") ? previous.sceneUrl : undefined;
    if (alreadyOpen) {
      this.prefabContext = { prefabUrl:url, revision:alreadyOpen.revision, ...(previousSceneUrl ? {previousSceneUrl} : {}) };
      return this.prefabContext;
    }
    await this.ensureSceneSwitchSafe();
    this.prefabContext = undefined;
    await Editor.Message.request("scene", "open-scene", asset.uuid);
    const tree = await this.waitTargetPrefab(asset);
    this.prefabContext = { prefabUrl:url, revision:tree.revision, ...(previousSceneUrl ? {previousSceneUrl} : {}) };
    return this.prefabContext;
  }

  prefabGetTree(): Promise<SceneSnapshot> {
    if (!this.prefabContext) throw new BridgeFault("INVALID_REQUEST", "No prefab is open");
    return this.executeScene<SceneSnapshot>("getTree");
  }

  async prefabApplyPatch(patch: ScenePatch): Promise<PatchResult> {
    if (!this.prefabContext) throw new BridgeFault("INVALID_REQUEST", "No prefab is open");
    assertDocumentCanAutoSave(await this.getSceneTree());
    const result = await this.executeScene<PatchResult>("applyPatch", patch);
    await savePatchOrRestore(
      () => this.saveScene(),
      () => this.executeScene<UndoResult>("undoLastWrite"),
      result.beforeRevision,
      () => this.executeScene("requireRecoveryRead"),
      () => this.executeScene("assertLastWriteCurrent"),
    );
    return { ...result, after: await this.executeScene<SceneSnapshot>("acceptLastWriteAfterSave") };
  }

  async prefabSave(): Promise<SceneSnapshot> {
    if (!this.prefabContext) throw new BridgeFault("INVALID_REQUEST", "No prefab is open");
    await this.saveScene();
    return this.prefabGetTree();
  }

  async prefabClose(): Promise<SceneSnapshot> {
    if (!this.prefabContext) throw new BridgeFault("INVALID_REQUEST", "No prefab is open");
    await Editor.Message.request("scene", "close-scene");
    this.prefabContext = undefined;
    await this.waitSceneReady();
    return this.getSceneTree();
  }

  async prefabInstantiate(request: PrefabInstantiateRequest): Promise<PatchResult> {
    const before = await this.getSceneTree();
    assertDocumentCanAutoSave(before);
    if (before.revision !== request.expectedRevision) {
      throw new BridgeFault("REVISION_CONFLICT", `Expected ${request.expectedRevision}, current revision is ${before.revision}`);
    }
    const asset = await this.assetGetInfo(request.url);
    if (!asset) throw new BridgeFault("NOT_FOUND", `${request.url} was not found`);
    const parentUuid = request.parentKey
      ? await this.executeScene<string>("getNodeUuid", request.parentKey)
      : undefined;
    const uuid = await Editor.Message.request("scene", "create-node", {
      ...(parentUuid ? { parent: parentUuid } : {}),
      assetUuid: asset.uuid,
      name: request.semanticKey.split(".").at(-1) ?? "Prefab",
      nameIncrease: false,
    }) as string;
    await this.executeScene("setSemanticKeyByUuid", { uuid, semanticKey: request.semanticKey });
    await this.saveScene();
    const after = await this.getSceneTree();
    return { transactionId: randomUUID(), beforeRevision: before.revision, after };
  }

  private async waitSceneReady(): Promise<void> {
    const deadline = Date.now() + 15_000;
    while (Date.now() < deadline) {
      if (await Editor.Message.request("scene", "query-is-ready")) return;
      await new Promise((resolve) => setTimeout(resolve, 200));
    }
    throw new BridgeFault("TIMEOUT", "Creator scene did not become ready");
  }

  /** Version-limited built-in scene messages, confirmed in the installed Creator 3.8.8 package. */
  private async readTargetPrefab(asset: AssetInfo): Promise<SceneSnapshot | undefined> {
    const identity = async () => {
      const ready = await Editor.Message.request("scene", "query-is-ready");
      const mode = await Editor.Message.request("scene", "query-scene-mode");
      const uuid = await Editor.Message.request("scene", "query-current-scene");
      if (typeof ready !== "boolean" || typeof mode !== "string" || typeof uuid !== "string" || !uuid.trim())
        throw new BridgeFault("INTERNAL_ERROR", "Creator Prefab identity response is incomplete; effect outcome is unknown");
      return ready === true && mode === "prefab" && uuid === asset.uuid;
    };
    if (!await identity()) return undefined;
    const current = await this.getSceneTree();
    if (current.sceneUrl !== asset.url || !Array.isArray(current.roots) || !current.revision) return undefined;
    return await identity() ? current : undefined;
  }

  private async waitTargetPrefab(asset: AssetInfo): Promise<SceneSnapshot> {
    const deadline = Date.now() + 15_000;
    while (Date.now() < deadline) {
      const current = await this.readTargetPrefab(asset);
      if (current) return current;
      await new Promise((resolve) => setTimeout(resolve, 200));
    }
    throw new BridgeFault("TIMEOUT", "Creator did not enter the requested Prefab", {targetUrl:asset.url,effectApplied:"UNKNOWN"});
  }

  /** A ready document can still be the previous scene; bind both observations to the requested asset. */
  private async readTargetScene(asset: AssetInfo): Promise<SceneSnapshot | undefined> {
    const identity = async () => {
      const ready = await Editor.Message.request("scene", "query-is-ready");
      if (typeof ready !== "boolean") throw new BridgeFault("INTERNAL_ERROR", "Creator scene readiness is unknown");
      if (!ready) return false;
      const mode = await Editor.Message.request("scene", "query-scene-mode");
      if (typeof mode !== "string") throw new BridgeFault("INTERNAL_ERROR", "Creator scene mode is unknown");
      if (mode !== "general") return false;
      const uuid = await Editor.Message.request("scene", "query-current-scene");
      if (typeof uuid !== "string" || !uuid.trim())
        throw new BridgeFault("INTERNAL_ERROR", "Creator scene identity is incomplete; effect outcome is unknown");
      return uuid === asset.uuid;
    };
    if (!await identity()) return undefined;
    const current = await this.getSceneTree();
    if (current.sceneUrl !== asset.url || !Array.isArray(current.roots) || !current.revision) return undefined;
    return await identity() ? current : undefined;
  }

  private async waitDocumentOpen(asset: AssetInfo): Promise<SceneSnapshot> {
    const deadline = Date.now() + 15_000;
    while (Date.now() < deadline) {
      const current = await this.readTargetScene(asset);
      if (current) return current;
      await new Promise((resolve) => setTimeout(resolve, 200));
    }
    throw new BridgeFault("TIMEOUT", "Creator did not enter the requested scene", { targetUrl: asset.url, effectApplied: "UNKNOWN" });
  }

  private sceneEffectUnknown(error: unknown, targetUrl: string, phase: string): never {
    throw new BridgeFault(error instanceof BridgeFault && error.code === "TIMEOUT" ? "TIMEOUT" : "INTERNAL_ERROR",
      "Scene effect outcome is unknown; inspect the original operation before retrying", {
        targetUrl, phase, effectApplied: "UNKNOWN",
        ...(error instanceof BridgeFault ? { originalCode: error.code } : {}),
      });
  }
}
