import { randomUUID } from "node:crypto";
import { BridgeFault } from "../../mcp/src/errors.js";
import type { NodeRef, SceneSnapshot } from "../../mcp/src/protocol.js";
import type { PatchResult } from "../../mcp/src/scene-adapter.js";
import { createNodeResolver, describeNodeRef } from "./node-resolve.js";
import { assertDocumentCanAutoSave } from "./document-save.js";

declare const Editor: {
  Message: { request(channel: string, message: string, ...args: unknown[]): Promise<unknown> };
};

type SceneSuccess<T> = { ok: true; result: T };
type SceneFailure = { ok: false; error: { code: string; message: string } };
type SceneResult<T> = SceneSuccess<T> | SceneFailure;

type PrefabDump = {
  rootUuid: string;
  uuid: string;
  prefabStateInfo?: {
    isApplicable?: boolean;
    isRevertable?: boolean;
  };
};

async function executeSceneScript<T>(method: string, argument?: unknown): Promise<T> {
  const response = (await Editor.Message.request("scene", "execute-scene-script", {
    name: "creator-ai-bridge",
    method,
    args: argument === undefined ? [] : [argument],
  })) as SceneResult<T>;
  if (!response.ok) {
    throw Object.assign(new Error(response.error.message), { code: response.error.code });
  }
  return response.result;
}

const { resolveNodeRef } = createNodeResolver(executeSceneScript);

async function getTree(): Promise<SceneSnapshot> {
  return executeSceneScript<SceneSnapshot>("getTree");
}

async function saveScene(): Promise<void> {
  await Editor.Message.request("scene", "save-scene");
}

function bridgeCode(value: string): BridgeFault["code"] {
  const allowed = new Set<BridgeFault["code"]>([
    "INVALID_REQUEST",
    "REVISION_CONFLICT",
    "NOT_FOUND",
    "UNSUPPORTED",
    "INTERNAL_ERROR",
    "TIMEOUT",
  ]);
  return allowed.has(value as BridgeFault["code"]) ? value as BridgeFault["code"] : "INVALID_REQUEST";
}

async function resolveTarget(target: NodeRef) {
  try {
    return await resolveNodeRef(target);
  } catch (error) {
    const code = bridgeCode((error as { code?: string }).code ?? "INVALID_REQUEST");
    const message = error instanceof Error ? error.message : String(error);
    throw new BridgeFault(code, `Failed to resolve ${describeNodeRef(target)}: ${message}`);
  }
}

function readPrefabDump(dump: unknown): PrefabDump | undefined {
  if (!dump || typeof dump !== "object") return undefined;
  const record = dump as Record<string, unknown>;
  const direct = record.__prefab__ as PrefabDump | undefined;
  if (direct?.rootUuid && direct?.uuid) return direct;
  const nested = (record.value as Record<string, unknown> | undefined)?.__prefab__ as PrefabDump | undefined;
  if (nested?.rootUuid && nested?.uuid) return nested;
  return undefined;
}

async function queryPrefabInstance(nodeUuid: string): Promise<PrefabDump> {
  let dump: unknown;
  try {
    dump = await Editor.Message.request("scene", "query-node", nodeUuid);
  } catch (error) {
    throw new BridgeFault(
      "UNSUPPORTED",
      `Creator scene IPC "query-node" is unavailable: ${error instanceof Error ? error.message : String(error)}`,
    );
  }
  const prefab = readPrefabDump(dump);
  if (!prefab) {
    throw new BridgeFault("INVALID_REQUEST", `Node ${nodeUuid} is not part of a Prefab instance`);
  }
  return prefab;
}

async function requestSceneIpc(message: string, ...args: unknown[]): Promise<void> {
  try {
    await Editor.Message.request("scene", message, ...args);
  } catch (error) {
    throw new BridgeFault(
      "UNSUPPORTED",
      `Creator scene IPC "${message}" is unavailable: ${error instanceof Error ? error.message : String(error)}`,
    );
  }
}

function assertRevision(before: SceneSnapshot, expectedRevision: string): void {
  if (before.revision !== expectedRevision) {
    throw new BridgeFault(
      "REVISION_CONFLICT",
      `Expected ${expectedRevision}, current revision is ${before.revision}`,
    );
  }
}

async function finishPatch(before: SceneSnapshot): Promise<PatchResult> {
  await saveScene();
  const after = await getTree();
  return { transactionId: randomUUID(), beforeRevision: before.revision, after };
}

/** Apply Prefab instance overrides to the linked Prefab asset. */
export async function prefabApplyInstance(target: NodeRef, expectedRevision: string): Promise<PatchResult> {
  const before = await getTree();
  assertDocumentCanAutoSave(before);
  assertRevision(before, expectedRevision);
  const resolved = await resolveTarget(target);
  const prefab = await queryPrefabInstance(resolved.uuid);
  if (prefab.prefabStateInfo?.isApplicable === false) {
    throw new BridgeFault("INVALID_REQUEST", "Prefab instance has no applicable overrides");
  }
  await requestSceneIpc("apply-prefab", prefab.rootUuid);
  return finishPatch(before);
}

/** Revert Prefab instance overrides back to the linked Prefab asset. */
export async function prefabRevertInstance(target: NodeRef, expectedRevision: string): Promise<PatchResult> {
  const before = await getTree();
  assertDocumentCanAutoSave(before);
  assertRevision(before, expectedRevision);
  const resolved = await resolveTarget(target);
  const prefab = await queryPrefabInstance(resolved.uuid);
  if (prefab.prefabStateInfo?.isRevertable === false) {
    throw new BridgeFault("INVALID_REQUEST", "Prefab instance has no revertable overrides");
  }
  await requestSceneIpc("restore-prefab", prefab.rootUuid, prefab.uuid);
  return finishPatch(before);
}
