/** One editor session owns one cache. Notifications invalidate both values and in-flight fills. */
export class NodeTreeCache<T> {
  private generation = 0;
  private value: { key: string; expires: number; data: T } | undefined;

  constructor(private readonly enabled: boolean, private readonly now = Date.now) {}

  private clone(data: T): T { return JSON.parse(JSON.stringify(data)) as T; }

  invalidate(): void {
    this.generation += 1;
    this.value = undefined;
  }

  async read(key: string, load: () => Promise<T>, fresh = false): Promise<T> {
    if (!this.enabled || fresh) {
      if (fresh) this.invalidate();
      return this.clone(await load());
    }
    const cached = this.value;
    if (cached?.key === key && cached.expires > this.now()) return this.clone(cached.data);
    const generation = this.generation;
    const data = await load();
    if (generation === this.generation) {
      this.value = { key, expires: this.now() + 2_000, data: this.clone(data) };
    }
    return this.clone(data);
  }
}
