import type {
  AssetDependencyGraph,
  AssetDependencyNode,
  EditorSelection,
  PerformanceSnapshot,
  PreviewStatus,
  RuntimeState,
  SceneNode,
  SceneSnapshot,
} from "../../mcp/src/protocol.js";

declare const Editor: {
  Project?: { path: string };
  Selection?: {
    getSelected?(type: string): string[];
    select?(type: string, uuids: string | string[]): void;
    unselect?(type: string, uuids: string | string[]): void;
    clear?(type: string): void;
  };
  Message: { request(channel: string, message: string, ...args: unknown[]): Promise<unknown> };
};

type RawAsset = {
  name?: string;
  url?: string;
  uuid?: string;
};

const DEFAULT_DEPTH = 5;

function countNodes(nodes: SceneNode[]): number {
  let total = 0;
  for (const node of nodes) {
    total += 1 + countNodes(node.children);
  }
  return total;
}

async function queryAssetInfo(urlOrUuid: string): Promise<RawAsset | null> {
  return (await Editor.Message.request("asset-db", "query-asset-info", urlOrUuid)) as RawAsset | null;
}

async function queryDependencies(urlOrUuid: string): Promise<string[]> {
  try {
    const deps = await Editor.Message.request("asset-db", "query-asset-dependencies", urlOrUuid, "all");
    return Array.isArray(deps) ? deps.filter((item): item is string => typeof item === "string") : [];
  } catch {
    return [];
  }
}

async function queryUsers(urlOrUuid: string): Promise<string[]> {
  try {
    const users = await Editor.Message.request("asset-db", "query-asset-users", urlOrUuid, "all");
    return Array.isArray(users) ? users.filter((item): item is string => typeof item === "string") : [];
  } catch {
    return [];
  }
}

async function resolveNode(urlOrUuid: string): Promise<AssetDependencyNode> {
  const info = await queryAssetInfo(urlOrUuid);
  if (!info) {
    return { url: urlOrUuid, missing: true };
  }
  const key = info.uuid ?? urlOrUuid;
  const dependents = await queryUsers(key);
  return {
    url: info.url ?? urlOrUuid,
    ...(info.uuid ? { uuid: info.uuid } : {}),
    ...(dependents.length ? { dependents } : {}),
  };
}

/** Walk AssetDB dependency edges up to `depth` (default 5, max 20). */
export async function inspectAssetDependencies(
  urlOrUuid: string,
  depth = DEFAULT_DEPTH,
): Promise<AssetDependencyGraph> {
  const maxDepth = Math.max(1, Math.min(20, depth));
  const rootInfo = await queryAssetInfo(urlOrUuid);
  const root = rootInfo?.url ?? rootInfo?.uuid ?? urlOrUuid;
  const nodesByKey = new Map<string, AssetDependencyNode>();
  const missing: string[] = [];
  const queue: Array<{ key: string; remaining: number }> = [];

  const rootNode = await resolveNode(urlOrUuid);
  const rootKey = rootNode.uuid ?? rootNode.url;
  nodesByKey.set(rootKey, rootNode);
  if (rootNode.missing) missing.push(rootNode.url);
  queue.push({ key: rootKey, remaining: maxDepth });

  while (queue.length) {
    const current = queue.shift()!;
    if (current.remaining <= 0) continue;
    const deps = await queryDependencies(current.key);
    for (const dep of deps) {
      const node = await resolveNode(dep);
      const key = node.uuid ?? node.url;
      if (node.missing && !missing.includes(node.url)) missing.push(node.url);
      if (!nodesByKey.has(key)) {
        nodesByKey.set(key, node);
        if (!node.missing) queue.push({ key, remaining: current.remaining - 1 });
      }
    }
  }

  return {
    root,
    nodes: [...nodesByKey.values()],
    missing,
    ok: missing.length === 0,
  };
}

/** Same graph walk as inspect; `ok` is false when any dependency is missing. */
export async function validateAssetDependencies(
  urlOrUuid: string,
  depth = DEFAULT_DEPTH,
): Promise<AssetDependencyGraph> {
  return inspectAssetDependencies(urlOrUuid, depth);
}

async function selectionUuids(type: "node" | "asset"): Promise<string[]> {
  try {
    if (typeof Editor.Selection?.getSelected === "function") {
      return Editor.Selection.getSelected(type) ?? [];
    }
  } catch {
    // fall through to message API
  }
  try {
    const value = await Editor.Message.request("selection", "query-select", type);
    return Array.isArray(value) ? value.filter((item): item is string => typeof item === "string") : [];
  } catch {
    try {
      const value = await Editor.Message.request("selection", "get-selected", type);
      return Array.isArray(value) ? value.filter((item): item is string => typeof item === "string") : [];
    } catch {
      return [];
    }
  }
}

async function applySelection(type: "node" | "asset", uuids: string[]): Promise<void> {
  try {
    if (typeof Editor.Selection?.clear === "function") Editor.Selection.clear(type);
    if (uuids.length && typeof Editor.Selection?.select === "function") {
      Editor.Selection.select(type, uuids);
      return;
    }
  } catch {
    // fall through
  }
  try {
    await Editor.Message.request("selection", "clear", type);
  } catch {
    // ignore
  }
  if (!uuids.length) return;
  try {
    await Editor.Message.request("selection", "select", type, uuids);
  } catch {
    await Editor.Message.request("selection", "select", type, uuids[0], uuids.slice(1));
  }
}

/** Best-effort read of current node/asset selection. */
export async function getEditorSelection(): Promise<EditorSelection> {
  const nodeUuids = await selectionUuids("node");
  const assetUuids = await selectionUuids("asset");
  const nodes: EditorSelection["nodes"] = await Promise.all(nodeUuids.map(async (uuid) => {
    try {
      const info = await Editor.Message.request("scene", "query-node", uuid) as {
        name?: string;
        path?: string;
        value?: { name?: string };
      } | null;
      const entry: EditorSelection["nodes"][number] = { uuid };
      const name = typeof info?.name === "string" ? info.name : info?.value?.name;
      if (typeof name === "string") entry.name = name;
      if (typeof info?.path === "string") entry.path = info.path;
      return entry;
    } catch {
      return { uuid };
    }
  }));
  const assets = await Promise.all(assetUuids.map(async (uuid) => {
    const info = await queryAssetInfo(uuid);
    return { uuid, ...(info?.url ? { url: info.url } : {}) };
  }));

  let type: EditorSelection["type"] = "none";
  if (nodes.length && assets.length) type = "mixed";
  else if (nodes.length) type = "node";
  else if (assets.length) type = "asset";

  return { type, nodes, assets };
}

/** Replace node and/or asset selection; returns the resulting selection. */
export async function setEditorSelection(selection: {
  nodeUuids?: string[];
  assetUuids?: string[];
}): Promise<EditorSelection> {
  if (selection.nodeUuids) await applySelection("node", selection.nodeUuids);
  if (selection.assetUuids) await applySelection("asset", selection.assetUuids);
  return getEditorSelection();
}

/** Best-effort editor-side metrics; unavailable fields stay null. */
export async function buildPerformanceSnapshot(
  getTree: () => Promise<SceneSnapshot>,
): Promise<PerformanceSnapshot> {
  const capturedAt = new Date().toISOString();
  let nodeCount: number | null = null;
  let memoryMb: number | null = null;
  const notes: string[] = [];

  try {
    const tree = await getTree();
    nodeCount = countNodes(tree.roots);
  } catch (error) {
    notes.push(error instanceof Error ? error.message : String(error));
  }

  try {
    memoryMb = Math.round((process.memoryUsage().heapUsed / (1024 * 1024)) * 10) / 10;
  } catch {
    notes.push("process.memoryUsage unavailable");
  }

  notes.push("drawCalls/fps are not exposed by the editor bridge; values left null");

  return {
    capturedAt,
    nodeCount,
    drawCalls: null,
    fps: null,
    memoryMb,
    message: notes.join("; "),
  };
}

/**
 * Runtime / preview state stub.
 * When GameTest is not wired, passthrough preview status with a readiness message.
 */
export function buildRuntimeState(preview: PreviewStatus): RuntimeState {
  return {
    preview,
    gameTestReady: false,
    message: "GameTest bridge is not ready; returning preview status only",
  };
}
