import type { JsonValue, NodeRef } from "../../mcp/src/protocol.js";
import { assertNodeRef } from "./node-resolve.js";

declare const Editor: {
  Message: { request(channel: string, message: string, ...args: unknown[]): Promise<unknown> };
};

type SceneSuccess<T> = { ok: true; result: T };
type SceneFailure = { ok: false; error: { code: string; message: string } };
type SceneResult<T> = SceneSuccess<T> | SceneFailure;

async function executeScene<T>(method: string, argument: unknown): Promise<T> {
  const response = (await Editor.Message.request("scene", "execute-scene-script", {
    name: "creator-ai-bridge",
    method,
    args: [argument],
  })) as SceneResult<T>;
  if (!response.ok) {
    throw Object.assign(new Error(response.error.message), { code: response.error.code });
  }
  return response.result;
}

function assertTarget(ref: NodeRef): NodeRef {
  assertNodeRef(ref);
  return ref;
}

export async function animationGetState(params: { target: NodeRef }): Promise<JsonValue> {
  return executeScene<JsonValue>("animationGetState", { target: assertTarget(params.target) });
}

export async function animationPlay(params: { target: NodeRef; clip?: string }): Promise<JsonValue> {
  return executeScene<JsonValue>("animationPlay", {
    target: assertTarget(params.target),
    ...(params.clip ? { clip: params.clip } : {}),
  });
}

export async function animationStop(params: { target: NodeRef }): Promise<JsonValue> {
  return executeScene<JsonValue>("animationStop", { target: assertTarget(params.target) });
}

export async function spineGetInfo(params: { target: NodeRef }): Promise<JsonValue> {
  return executeScene<JsonValue>("spineGetInfo", { target: assertTarget(params.target) });
}

export async function spinePlay(params: { target: NodeRef; animation: string; loop?: boolean }): Promise<JsonValue> {
  return executeScene<JsonValue>("spinePlay", {
    target: assertTarget(params.target),
    animation: params.animation,
    ...(params.loop !== undefined ? { loop: params.loop } : {}),
  });
}

export async function spineSetSkin(params: { target: NodeRef; skin: string }): Promise<JsonValue> {
  return executeScene<JsonValue>("spineSetSkin", {
    target: assertTarget(params.target),
    skin: params.skin,
  });
}
