import { createHash } from "node:crypto";
import { basename } from "node:path";

export function projectMcpName(projectPath: string): string {
  const slug = basename(projectPath)
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "")
    .slice(0, 32) || "project";
  const fingerprint = createHash("sha256").update(projectPath).digest("hex").slice(0, 8);
  return `cocos-creator-${slug}-${fingerprint}`;
}
