export async function uiBuildTree(params: {
  parent?: NodeRef;
  expectedRevision: string;
  tree: UiNodeSpec;
  verify: true;
  save: true;
}): Promise<UiBuildResult> {
  const resolved = await resolveParent(params.parent);
  const parentKey = resolved.key;
  const { patch, createdRoots } = await buildPatchFromTree(params.tree, parentKey, params.expectedRevision);
  patch.operations.unshift(...resolved.operations);
  const after = await applyPatchWithSave(patch);
  const rootKeys = createdRoots.length > 0 ? createdRoots : [nodeKeyForSpec(params.tree, parentKey, parentKey ?? params.tree.name)];
  const nodeUuids = after.nodeUuids ?? {};
  const targets = Object.values(nodeUuids).map((uuid) => `uuid:${uuid}`);
  const warnings = targets.length ? await executeScene<string[]>("uiCheckUiBounds", targets) : ["Created-node identities unavailable; bounds were not checked"];
  const viewportContext = await executeScene<UiBuildResult["viewportContext"]>("uiGetViewportContext", nodeUuids[rootKeys[0]!] ? `uuid:${nodeUuids[rootKeys[0]!]}` : parentKey);
  return {
    ok: true,
    revision: after.revision,
    roots: rootKeys,
    nodeUuids,
    warnings,
    ...(viewportContext ? { viewportContext } : {}),
  };
}

export async function uiListFonts(): Promise<Array<{ url: string; uuid: string; name?: string }>> {
  const raw = (await Editor.Message.request("asset-db", "query-assets", {
    pattern: "db://assets/**",
  })) as RawAsset[];
  const fonts: Array<{ url: string; uuid: string; name?: string }> = [];
  for (const asset of raw ?? []) {
    const url = asset.url ?? "";
    const isFontAsset = url.endsWith(".ttf") || url.endsWith(".otf") || url.endsWith(".fnt")
      || asset.type === "cc.TTFFont" || asset.type === "cc.BitmapFont";
    if (!isFontAsset || !asset.uuid || !url.startsWith("db://assets/")) continue;
    fonts.push({
      url,
      uuid: asset.uuid,
      ...(asset.name ? { name: asset.name } : {}),
    });
  }
  return fonts.sort((a, b) => a.url.localeCompare(b.url));
}

async function patchTargetProperties(
  target: NodeRef,
  expectedRevision: string,
  buildOps: (targetKey: string) => Promise<PatchOperation[]>,
): Promise<JsonValue> {
  const targetKey = await resolveTargetKey(target);
  const tree = await executeScene<SceneSnapshot>("getTree", { acknowledgeRecovery: false });
  const operations = await buildOps(targetKey);
  const after = await applyPatchWithSave({
    expectedRevision: expectedRevision ?? tree.revision,
    verify: true,
    save: true,
    operations,
  });
  return { ok: true, target: targetKey, revision: after.revision };
}

export async function uiSetLabel(params: {
  target: NodeRef;
  string?: string;
  fontSize?: number;
  fontUuid?: string;
  color?: { r: number; g: number; b: number; a: number };
  expectedRevision?: string;
}): Promise<JsonValue> {
  const tree = await executeScene<SceneSnapshot>("getTree", { acknowledgeRecovery: false });
  return patchTargetProperties(params.target, params.expectedRevision ?? tree.revision, async (targetKey) => {
    const ops: PatchOperation[] = [
      { op: "upsertComponent", target: targetKey, type: "Label", properties: {} },
    ];
    if (params.string !== undefined) {
      ops.push({ op: "setProperty", target: targetKey, component: "Label", property: "string", value: params.string });
    }
    if (params.fontSize !== undefined) {
      ops.push({ op: "setProperty", target: targetKey, component: "Label", property: "fontSize", value: params.fontSize });
      ops.push({ op: "setProperty", target: targetKey, component: "Label", property: "lineHeight", value: params.fontSize });
    }
    if (params.color) {
      ops.push({
        op: "setProperty",
        target: targetKey,
        component: "Label",
        property: "color",
        value: { $type: "Color", ...params.color },
      });
    }
    if (params.fontUuid) {
      const asset = await assetReferenceFromUuid(params.fontUuid);
      ops.push({ op: "bindAsset", target: targetKey, component: "Label", property: "font", asset });
    }
    return ops;
  });
}

export async function uiSetRichText(params: {
  target: NodeRef;
  string?: string;
  fontSize?: number;
  maxWidth?: number;
  expectedRevision?: string;
}): Promise<JsonValue> {
  const tree = await executeScene<SceneSnapshot>("getTree", { acknowledgeRecovery: false });
  return patchTargetProperties(params.target, params.expectedRevision ?? tree.revision, async (targetKey) => {
    const ops: PatchOperation[] = [
      { op: "upsertComponent", target: targetKey, type: "RichText", properties: {} },
    ];
    if (params.string !== undefined) {
      ops.push({ op: "setProperty", target: targetKey, component: "RichText", property: "string", value: params.string });
    }
    if (params.fontSize !== undefined) {
      ops.push({ op: "setProperty", target: targetKey, component: "RichText", property: "fontSize", value: params.fontSize });
    }
    if (params.maxWidth !== undefined) {
      ops.push({ op: "setProperty", target: targetKey, component: "RichText", property: "maxWidth", value: params.maxWidth });
    }
    return ops;
  });
}

export async function uiAssignFont(params: { target: NodeRef; fontUuid: string; expectedRevision?: string }): Promise<JsonValue> {
  const tree = await executeScene<SceneSnapshot>("getTree", { acknowledgeRecovery: false });
  return patchTargetProperties(params.target, params.expectedRevision ?? tree.revision, async (targetKey) => {
    const asset = await assetReferenceFromUuid(params.fontUuid);
    return [
      { op: "upsertComponent", target: targetKey, type: "Label", properties: {} },
      { op: "bindAsset", target: targetKey, component: "Label", property: "font", asset },
    ];
  });
}
