import { homedir } from "node:os";
import { join } from "node:path";

/** 返回 Companion 用户数据目录（按平台落在 Application Support / AppData / XDG）。 */
export function companionDataDirectory(
  home = homedir(),
  platform: NodeJS.Platform = process.platform,
): string {
  if (platform === "darwin") {
    return join(home, "Library", "Application Support", "Creator AI Companion");
  }
  if (platform === "win32") {
    const appData = process.env.APPDATA && home === homedir()
      ? process.env.APPDATA
      : join(home, "AppData", "Roaming");
    return join(appData, "Creator AI Companion");
  }
  return join(home, ".local", "share", "creator-ai-companion");
}

/** 工程注册表 JSON 文件路径。 */
export function projectRegistryPath(home = homedir(), platform: NodeJS.Platform = process.platform): string {
  return join(companionDataDirectory(home, platform), "projects.json");
}

/** MCP 工具方案及各工程当前选择的持久化文件路径。 */
export function toolPresetStorePath(home = homedir(), platform: NodeJS.Platform = process.platform): string {
  return join(companionDataDirectory(home, platform), "tool-presets.json");
}

/** 调试日志落盘目录路径。 */
export function companionLogDirectory(home = homedir(), platform: NodeJS.Platform = process.platform): string {
  return join(companionDataDirectory(home, platform), "logs");
}

/** 守护进程定位文件（baseUrl / token）路径。 */
export function daemonLocatorPath(home = homedir(), platform: NodeJS.Platform = process.platform): string {
  return join(companionDataDirectory(home, platform), "daemon.json");
}

/** Bridge 受管安装登记文件路径。 */
export function bridgeInstallRegistryPath(home = homedir(), platform: NodeJS.Platform = process.platform): string {
  return join(companionDataDirectory(home, platform), "bridge-installs.json");
}

/** Project write lease and side-effect outcome database. */
export function coordinationStorePath(home = homedir(), platform: NodeJS.Platform = process.platform): string {
  return join(companionDataDirectory(home, platform), "coordination.sqlite");
}
