import { WebSocketServer, type WebSocket } from "ws";
import { BridgeService } from "./bridge-service.js";
import type { BridgeRequest, BridgeResponse } from "./protocol.js";

/** Bridge WebSocket 服务监听地址。 */
export interface BridgeServerAddress {
  host: "127.0.0.1";
  port: number;
}

/** 将 BridgeService 暴露为本地 WebSocket 服务。 */
export class WsBridgeServer {
  private server: WebSocketServer | undefined;

  /** 绑定业务服务与最大报文尺寸。 */
  constructor(
    private readonly service: BridgeService,
    private readonly maxPayloadBytes = 1024 * 1024,
  ) {}

  /** 在 127.0.0.1 上启动监听，port=0 时由系统分配端口。 */
  async start(port = 0): Promise<BridgeServerAddress> {
    if (this.server) throw new Error("Bridge server is already running");
    const server = new WebSocketServer({
      host: "127.0.0.1",
      port,
      maxPayload: this.maxPayloadBytes,
    });
    this.server = server;
    server.on("connection", (socket) => this.attach(socket));
    await new Promise<void>((resolve, reject) => {
      server.once("listening", resolve);
      server.once("error", reject);
    });
    const address = server.address();
    if (!address || typeof address === "string") throw new Error("Expected TCP bridge address");
    return { host: "127.0.0.1", port: address.port };
  }

  /** 终止所有客户端连接并关闭服务器。 */
  async stop(): Promise<void> {
    const server = this.server;
    this.server = undefined;
    if (!server) return;
    for (const client of server.clients) client.terminate();
    await new Promise<void>((resolve, reject) =>
      server.close((error) => (error ? reject(error) : resolve())),
    );
  }

  /** 将单个 WebSocket 连接接到请求处理与响应回写。 */
  private attach(socket: WebSocket): void {
    socket.on("error", () => socket.terminate());
    socket.on("message", async (data) => {
      let response: BridgeResponse;
      try {
        const request = JSON.parse(data.toString()) as BridgeRequest;
        response = await this.service.handle(request);
      } catch (error) {
        response = {
          id: "unknown",
          ok: false,
          error: {
            code: "INVALID_REQUEST",
            message: error instanceof Error ? error.message : "Invalid JSON request",
          },
        };
      }
      if (socket.readyState === socket.OPEN) socket.send(JSON.stringify(response));
    });
  }
}
