import type { JsonValue, NodeRef } from "../../mcp/src/protocol.js";
import { createNodeResolver, describeNodeRef } from "./node-resolve.js";

declare const Editor: {
  Message: { request(channel: string, message: string, ...args: unknown[]): Promise<unknown> };
};

type SceneSuccess<T> = { ok: true; result: T };
type SceneFailure = { ok: false; error: { code: string; message: string } };
type SceneResult<T> = SceneSuccess<T> | SceneFailure;

async function executeSceneScript<T>(method: string, argument?: unknown): Promise<T> {
  const response = (await Editor.Message.request("scene", "execute-scene-script", {
    name: "creator-ai-bridge",
    method,
    args: argument === undefined ? [] : [argument],
  })) as SceneResult<T>;
  if (!response.ok) {
    throw Object.assign(new Error(response.error.message), { code: response.error.code });
  }
  return response.result;
}

const { resolveNodeRef } = createNodeResolver(executeSceneScript);

async function resolveTarget(target: NodeRef) {
  try {
    const resolved = await resolveNodeRef(target);
    return { uuid: resolved.uuid, resolved };
  } catch (error) {
    const code = (error as { code?: string }).code ?? "INVALID_REQUEST";
    const message = error instanceof Error ? error.message : String(error);
    throw Object.assign(new Error(`Failed to resolve ${describeNodeRef(target)}: ${message}`), { code });
  }
}

export async function simulateButtonClick(params: { target: NodeRef }): Promise<JsonValue> {
  const { uuid, resolved } = await resolveTarget(params.target);
  const result = await executeSceneScript<{ uuid: string; handlerCount: number; invokedHandlers: number }>(
    "inputSimulateButtonClick",
    { uuid },
  );
  return { ok: true, target: resolved, ...result };
}

export async function bindButtonClickEvent(params: {
  target: NodeRef;
  handlerComponent: string;
  handlerMethod: string;
}): Promise<JsonValue> {
  const { uuid, resolved } = await resolveTarget(params.target);
  const result = await executeSceneScript<{ uuid: string; handlerCount: number }>("inputBindButtonClickEvent", {
    uuid,
    handlerComponent: params.handlerComponent,
    handlerMethod: params.handlerMethod,
  });
  return { ok: true, target: resolved, ...result };
}

export async function simulateKeyPress(params: { key: string; type?: "down" | "up" | "press" }): Promise<JsonValue> {
  return executeSceneScript<JsonValue>("inputSimulateKeyPress", params);
}

export async function simulateMouseClick(params: { x: number; y: number }): Promise<JsonValue> {
  return executeSceneScript<JsonValue>("inputSimulateMouseClick", params);
}

export async function simulateMouseDrag(params: {
  fromX: number;
  fromY: number;
  toX: number;
  toY: number;
}): Promise<JsonValue> {
  return executeSceneScript<JsonValue>("inputSimulateMouseDrag", params);
}
