import { z } from "zod";

export const PROTOCOL_VERSION = "0.4.0";

export type JsonValue =
  | null
  | boolean
  | number
  | string
  | JsonValue[]
  | { [key: string]: JsonValue };

export interface SceneComponent {
  type: string;
  properties: Record<string, JsonValue>;
}

export interface SceneNode {
  key: string;
  uuid?: string;
  active?: boolean;
  position?: { x: number; y: number; z: number };
  rotation?: { x: number; y: number; z: number; w: number };
  scale?: { x: number; y: number; z: number };
  layer?: number;
  semanticKey?: string;
  name: string;
  components: SceneComponent[];
  children: SceneNode[];
}

export interface SceneSnapshot {
  sceneUrl: string;
  revision: string;
  roots: SceneNode[];
}

export type PatchOperation =
  | {
      op: "upsertNode";
      key: string;
      parent?: string;
      name: string;
      uiMode?: "auto" | "on" | "off";
    }
  | {
      op: "upsertComponent";
      target: string;
      type: string;
      properties?: Record<string, JsonValue>;
    }
  | {
      op: "setProperty";
      target: string;
      component: string;
      property: string;
      value: JsonValue;
    }
  | {
      op: "bindAsset";
      target: string;
      component: string;
      property: string;
      asset: AssetReference;
    }
  | {
      op: "removeNode";
      target: string;
      confirmation: string;
    };

export interface ScenePatch {
  expectedRevision: string;
  operations: PatchOperation[];
  verify: true;
  save: true;
}

export type BridgeMethod =
  | "creator.ping"
  | "creator.projectInfo"
  | "creator.hasUnsavedChanges"
  | "scene.getTree"
  | "scene.open"
  | "scene.list"
  | "scene.create"
  | "scene.save"
  | "scene.validate"
  | "scene.applyPatch"
  | "scene.undoLastWrite"
  | "asset.list"
  | "asset.search"
  | "asset.getInfo"
  | "asset.import"
  | "asset.refresh"
  | "asset.resolveReference"
  | "asset.delete"
  | "asset.inspectDependencies"
  | "asset.validateDependencies"
  | "script.write"
  | "script.waitCompile"
  | "script.getErrors"
  | "script.findComponent"
  | "script.executeScene"
  | "script.executeEditor"
  | "component.listAvailable"
  | "component.getSchema"
  | "debug.sceneLogs"
  | "prefab.probe"
  | "prefab.create"
  | "prefab.open"
  | "prefab.getTree"
  | "prefab.applyPatch"
  | "prefab.save"
  | "prefab.close"
  | "prefab.instantiate"
  | "prefab.applyInstance"
  | "prefab.revertInstance"
  | "preview.probe"
  | "preview.start"
  | "preview.status"
  | "preview.reload"
  | "preview.stop"
  | "preview.getMode"
  | "preview.setMode"
  | "capture.scene"
  | "capture.preview"
  | "capture.editor"
  | "editor.getSelection"
  | "editor.setSelection"
  | "editor.view.getStatus"
  | "editor.view.focus"
  | "editor.view.setMode"
  | "editor.view.setGrid"
  | "editor.view.reset"
  | "editor.performanceSnapshot"
  | "editor.runtimeState"
  | "ui.createCanvas"
  | "ui.createLabel"
  | "ui.createButton"
  | "ui.createSprite"
  | "ui.createEditBox"
  | "ui.createRichText"
  | "ui.createScrollView"
  | "ui.buildTree"
  | "ui.applyTemplate"
  | "ui.listFonts"
  | "ui.setLabel"
  | "ui.setRichText"
  | "ui.assignFont"
  | "ui.captureDesignResolutions"
  | "input.simulateButtonClick"
  | "input.bindButtonClickEvent"
  | "input.simulateKeyPress"
  | "input.simulateMouseClick"
  | "input.simulateMouseDrag"
  | "scene.snapshotCreate"
  | "scene.snapshotDiff"
  | "animation.getState"
  | "animation.play"
  | "animation.stop"
  | "spine.getInfo"
  | "spine.play"
  | "spine.setSkin"
  | "viewport.setReferenceImage"
  | "viewport.clearReferenceImage"
  | "viewport.getReferenceImage";

export interface BridgeRequest {
  id: string;
  token: string;
  protocolVersion: string;
  method: BridgeMethod;
  params?: JsonValue;
}

export interface BridgeError {
  code:
    | "UNAUTHORIZED"
    | "PROTOCOL_MISMATCH"
    | "INVALID_REQUEST"
    | "REVISION_CONFLICT"
    | "NOT_FOUND"
    | "NO_UNDO"
    | "ALREADY_EXISTS"
    | "HASH_CONFLICT"
    | "COMPILE_FAILED"
    | "UNSUPPORTED"
    | "CAPABILITY_DENIED"
    | "TIMEOUT"
    | "INTERNAL_ERROR";
  message: string;
  details?: JsonValue;
}

export type BridgeResponse =
  | { id: string; ok: true; result: JsonValue }
  | { id: string; ok: false; error: BridgeError };

export interface ProjectInfo {
  projectPath: string;
  projectFingerprint: string;
  creatorVersion: string;
  sessionId: string;
  protocolVersion: string;
  runtime: "creator" | "memory";
  /** 当前 BridgeService 实际生效的能力档位；旧 Bridge 响应可能缺失。 */
  capabilityProfile?: CapabilityProfile;
}

export interface ConnectionInfo {
  host: "127.0.0.1";
  port: number;
  token: string;
  protocolVersion: string;
  projectPath: string;
  projectFingerprint: string;
  creatorVersion: string;
  sessionId: string;
  createdAt: string;
  creatorPid?: number | undefined;
}

export const ConnectionInfoSchema = z
  .object({
    host: z.literal("127.0.0.1"),
    port: z.number().int().min(1).max(65_535),
    token: z.string().min(1),
    protocolVersion: z.literal(PROTOCOL_VERSION),
    projectPath: z.string().min(1),
    projectFingerprint: z.string().min(1),
    creatorVersion: z.string().min(1),
    sessionId: z.string().min(1),
    createdAt: z.iso.datetime(),
    creatorPid: z.number().int().positive().optional(),
  })
  .strict();

export interface AssetReference {
  url: string;
  subAsset?: string | undefined;
}

export type StructuredPropertyValue =
  | { $type: "Vec2"; x: number; y: number }
  | { $type: "Vec3"; x: number; y: number; z: number }
  | { $type: "Size"; width: number; height: number }
  | { $type: "Color"; r: number; g: number; b: number; a: number }
  | { $type: "NodeReference"; semanticKey: string }
  | { $type: "ComponentReference"; node: string; type: string };

export interface AssetInfo {
  url: string;
  uuid: string;
  path?: string;
  name?: string;
  type?: string;
  imported?: boolean;
  hash?: string;
  subAssets?: AssetInfo[];
}

export type EditorViewMode = "2d" | "3d";

export interface EditorViewStatus {
  mode: EditorViewMode | null;
  gridVisible: boolean | null;
  supported: {
    mode: boolean;
    grid: boolean;
    focus: boolean;
    reset: boolean;
  };
}

export interface EditorViewFocusResult {
  focusedNodeUuids: string[];
}

export interface EditorViewResetResult {
  reset: true;
}

export interface AssetImportRequest {
  sourcePath: string;
  destinationUrl: string;
}

export interface AssetDeleteRequest {
  url: string;
  expectedHash: string;
  confirmation: string;
  verify: true;
}

export type CapabilityProfile = "read-only" | "authoring" | "full-control";

export interface DiagnosticSnapshot {
  generatedAt: string;
  capabilityProfile: CapabilityProfile;
  project: ProjectInfo;
  document?: Pick<SceneSnapshot, "sceneUrl" | "revision">;
  audit: AuditEvent[];
}

export interface ScriptWriteRequest {
  url: string;
  content: string;
  expectedHash: string | null;
}

export interface CompileRequest {
  url: string;
  className?: string | undefined;
  timeoutMs?: number | undefined;
}

export interface CompileResult {
  status: "compiled" | "failed" | "timeout";
  imported: boolean;
  componentRegistered?: boolean;
  errors: string[];
}

export interface ComponentSchemaProperty {
  name: string;
  type: string;
  readonly: boolean;
  array?: boolean;
  assetType?: string;
  nodeReference?: boolean;
  /** Enum member names in declaration order. Numeric values stay on the Creator side. */
  enumNames?: string[];
}

export interface ComponentSchema {
  name: string;
  properties: ComponentSchemaProperty[];
}

export interface PrefabCreateRequest {
  sourceNodeKey: string;
  url: string;
}

export interface PrefabInstantiateRequest {
  url: string;
  parentKey?: string | undefined;
  semanticKey: string;
  expectedRevision: string;
}

export interface PrefabContext {
  prefabUrl: string;
  previousSceneUrl?: string;
  revision: string;
}

export interface PreviewStatus {
  available: boolean;
  running: boolean;
  url?: string;
  connections?: number;
  startedAt?: string;
  sessionId?: string;
  stopSupported: boolean;
  message?: string;
}

export interface ScreenshotResult {
  mimeType: "image/png";
  base64: string;
  path?: string;
  width: number;
  height: number;
  source: "scene" | "preview" | "editor";
  capturedAt: string;
}

export interface SceneListItem {
  url: string;
  uuid: string;
  name?: string;
}

export interface SceneValidateIssue {
  code: string;
  severity: "error" | "warning";
  message: string;
  nodeKey?: string;
  nodePath?: string;
}

export interface SceneValidateResult {
  ok: boolean;
  sceneUrl: string;
  revision: string;
  issues: SceneValidateIssue[];
  checks: {
    reopenable: boolean;
    componentsIntact: boolean;
    referencesValid: boolean;
    consoleBlockingErrors: boolean;
  };
}

export interface ExecuteScriptRequest {
  code: string;
  timeoutMs?: number;
  confirm: string;
}

export interface ExecuteScriptResult {
  ok: boolean;
  result?: JsonValue;
  logs?: string[];
  truncated?: boolean;
}

export interface AssetDependencyNode {
  url: string;
  uuid?: string;
  missing?: boolean;
  dependents?: string[];
}

export interface AssetDependencyGraph {
  root: string;
  nodes: AssetDependencyNode[];
  missing: string[];
  ok: boolean;
}

export interface EditorSelection {
  type: "node" | "asset" | "mixed" | "none";
  nodes: Array<{ uuid: string; name?: string; path?: string }>;
  assets: Array<{ uuid: string; url?: string }>;
}

export interface PerformanceSnapshot {
  capturedAt: string;
  nodeCount?: number | null;
  drawCalls?: number | null;
  fps?: number | null;
  memoryMb?: number | null;
  message?: string;
}

export interface RuntimeState {
  preview: PreviewStatus;
  gameTestReady: boolean;
  state?: JsonValue;
  message?: string;
}

export interface BuildStatus {
  state: "idle" | "running" | "passed" | "passed_with_warning" | "failed";
  platform: "web-mobile";
  operationId?: string;
  startedAt?: string;
  finishedAt?: string;
  outputDir?: string;
  logPath?: string;
  configPath?: string;
  error?: string;
  warning?: string;
  runnerExitCode?: number | null;
  runnerSignal?: string;
  builderFinished?: boolean;
  artifactIdentity?: {
    sourceRevision: string;
    buildConfigHash: string;
    packageHash: string;
    creatorVersion: string;
  };
}

/** Unified node addressing for ecosystem tools. */
export interface NodeRef {
  uuid?: string;
  path?: string;
  semanticKey?: string;
  name?: string;
}

export type PreviewMode = "browser" | "gameView" | "simulator";

export interface PreviewModeInfo {
  mode: PreviewMode;
  url?: string;
  message?: string;
}

export interface UiNodeSpec {
  name: string;
  type?: "node" | "canvas" | "label" | "button" | "sprite" | "editbox" | "richtext" | "scrollview";
  semanticKey?: string;
  position?: { x: number; y: number; z?: number };
  size?: { width: number; height: number };
  anchor?: { x: number; y: number };
  widget?: {
    top?: number;
    bottom?: number;
    left?: number;
    right?: number;
    horizontalCenter?: number;
    verticalCenter?: number;
    isAlignTop?: boolean;
    isAlignBottom?: boolean;
    isAlignLeft?: boolean;
    isAlignRight?: boolean;
    isAlignHorizontalCenter?: boolean;
    isAlignVerticalCenter?: boolean;
    isAbsoluteTop?: boolean;
    isAbsoluteBottom?: boolean;
    isAbsoluteLeft?: boolean;
    isAbsoluteRight?: boolean;
  };
  layout?: {
    type: "NONE" | "HORIZONTAL" | "VERTICAL" | "GRID";
    resizeMode?: "NONE" | "CHILDREN" | "CONTAINER";
    spacingX?: number;
    spacingY?: number;
    paddingLeft?: number;
    paddingRight?: number;
    paddingTop?: number;
    paddingBottom?: number;
    startAxis?: "HORIZONTAL" | "VERTICAL";
  };
  label?: { string: string; fontSize?: number; fontUuid?: string; color?: { r: number; g: number; b: number; a: number } };
  richText?: { string: string; fontSize?: number; maxWidth?: number };
  sprite?: { spriteFrameUuid?: string; type?: string; sizeMode?: string };
  button?: { transition?: string; target?: string };
  children?: UiNodeSpec[];
}

export interface UiBuildResult {
  ok: boolean;
  revision: string;
  roots: string[];
  warnings: string[];
  viewportContext?: {
    designWidth?: number;
    designHeight?: number;
    visibleWidth?: number;
    visibleHeight?: number;
    visibleOriginX?: number;
    visibleOriginY?: number;
    source?: "project-settings" | "editor-view" | "canvas" | "unknown";
    status?: "known" | "partial" | "unknown";
    canvasUuid?: string;
    canvasWidth?: number;
    canvasHeight?: number;
    resolutionPolicy?: number;
    runtimeVisible?: "unknown";
  };
  createdNodes?: Record<string, string>;
  nodeUuids?: Record<string, string>;
  automated?: string[];
}

export interface SceneSnapshotRecord {
  id: string;
  sceneUrl: string;
  revision: string;
  treeHash: string;
  screenshotPaths?: string[];
  createdAt: string;
}

export interface AuditEvent {
  id: string;
  method: BridgeMethod;
  startedAt: string;
  durationMs: number;
  ok: boolean;
  summary: string;
  errorCode?: BridgeError["code"];
  revision?: string;
  hash?: string;
}

export interface PanelState {
  connected: boolean;
  project: ProjectInfo;
  document?: SceneSnapshot;
  audit: AuditEvent[];
  capabilityProfile: CapabilityProfile;
}
