import { createHash } from "node:crypto";
import { mkdir, readFile, stat, writeFile } from "node:fs/promises";
import { isAbsolute, join } from "node:path";
import type { JsonValue } from "../../mcp/src/protocol.js";
import { BridgeFault } from "../../mcp/src/errors.js";

declare const Editor: {
  Project: { path: string };
  Message: { request(channel: string, message: string, ...args: unknown[]): Promise<unknown> };
};

type Parameters = { path?: string; url?: string; opacity?: number; visible?: boolean; offsetX?: number; offsetY?: number; scale?: number };
type State = Required<Pick<Parameters, "opacity" | "visible" | "offsetX" | "offsetY" | "scale">> & { absolutePath: string };
type EditorImage = { path?: string; x?: number; y?: number; sx?: number; sy?: number; opacity?: number; missing?: boolean };
const MAX_IMAGE_BYTES = 8 * 1024 * 1024;
let state: State | null = null;

function imageMime(data: Buffer): string | undefined {
  return data.subarray(0, 8).equals(Buffer.from([137, 80, 78, 71, 13, 10, 26, 10])) ? "image/png"
    : data[0] === 255 && data[1] === 216 && data[2] === 255 ? "image/jpeg"
      : data.toString("ascii", 0, 4) === "RIFF" && data.toString("ascii", 8, 12) === "WEBP" ? "image/webp" : undefined;
}

async function request(message: string, ...args: unknown[]): Promise<unknown> {
  return Editor.Message.request("reference-image", message, ...args);
}

async function readImage(path: string): Promise<{ base64: string; mimeType: string; width: number; height: number }> {
  const info = await stat(path).catch(() => null);
  if (!info?.isFile()) throw new BridgeFault("NOT_FOUND", `Reference image file not found: ${path}`);
  if (info.size > MAX_IMAGE_BYTES) throw new BridgeFault("INVALID_REQUEST", "Reference image must be at most 8 MiB");
  const data = await readFile(path);
  const mimeType = imageMime(data);
  if (!mimeType) throw new BridgeFault("INVALID_REQUEST", "Reference image must contain PNG, JPEG, or WebP image data");
  const electronModule = "electron";
  const { nativeImage } = require(electronModule) as { nativeImage: { createFromBuffer(data: Buffer): { isEmpty(): boolean; getSize(): { width: number; height: number } } } };
  const image = nativeImage.createFromBuffer(data);
  if (image.isEmpty()) throw new BridgeFault("INVALID_REQUEST", "Reference image could not be decoded");
  return { base64: data.toString("base64"), mimeType, ...image.getSize() };
}

async function resolvePath(source: string): Promise<string> {
  if (source.startsWith("db://")) {
    const info = await Editor.Message.request("asset-db", "query-asset-info", source) as { file?: string } | null;
    if (!info?.file) throw new BridgeFault("NOT_FOUND", `Asset not found: ${source}`);
    return info.file;
  }
  if (/^https?:\/\//.test(source)) {
    const response = await fetch(source, { signal: AbortSignal.timeout(15000) });
    if (!response.ok || !response.body) throw new BridgeFault("INVALID_REQUEST", `Reference image download failed: HTTP ${response.status}`);
    const chunks: Uint8Array[] = [];
    let size = 0;
    const reader = response.body.getReader();
    try {
      for (;;) {
        const chunk = await reader.read();
        if (chunk.done) break;
        size += chunk.value.length;
        if (size > MAX_IMAGE_BYTES) throw new BridgeFault("INVALID_REQUEST", "Reference image must be at most 8 MiB");
        chunks.push(chunk.value);
      }
    } finally { await reader.cancel(); }
    const directory = join(Editor.Project.path, "temp", "creator-ai-bridge", "reference-images");
    await mkdir(directory, { recursive: true });
    const data = Buffer.concat(chunks);
    const mime = imageMime(data);
    if (!mime) throw new BridgeFault("INVALID_REQUEST", "Reference download is not PNG, JPEG, or WebP image data");
    const extension = mime === "image/jpeg" ? "jpg" : mime === "image/webp" ? "webp" : "png";
    const path = join(directory, `${createHash("sha256").update(data).digest("hex")}.${extension}`);
    await writeFile(path, data);
    return path;
  }
  return isAbsolute(source) ? source : join(Editor.Project.path, source);
}

async function currentImage(): Promise<EditorImage | null> {
  return await request("query-current") as EditorImage | null;
}

function payload(current: EditorImage | null, unsupported?: string): JsonValue {
  const configured = Boolean(current?.path && !current.missing);
  return {
    ok: true, state, status: unsupported ? "unsupported" : configured ? "configured" : "empty",
    overlay: unsupported ? "state-only" : "reference-image-ipc", rendered: false,
    renderVerification: "not-verified", editor: current as JsonValue,
    message: unsupported ?? "Official reference-image configuration read back; actual scene-view rendering must be checked with an editor screenshot. Offsets use the Creator reference-image editor coordinates.",
  };
}

export async function setReferenceImage(params: Parameters): Promise<JsonValue> {
  const source = params.path ?? params.url ?? state?.absolutePath;
  if (!source) throw new BridgeFault("INVALID_REQUEST", "path or url is required");
  const absolutePath = await resolvePath(source);
  await readImage(absolutePath);
  const next: State = { absolutePath, opacity: params.opacity ?? state?.opacity ?? 0.5,
    visible: params.visible ?? state?.visible ?? true, offsetX: params.offsetX ?? state?.offsetX ?? 0,
    offsetY: params.offsetY ?? state?.offsetY ?? 0, scale: params.scale ?? state?.scale ?? 1 };
  if (![next.opacity, next.offsetX, next.offsetY, next.scale].every(Number.isFinite) || next.opacity < 0 || next.opacity > 1 || next.scale <= 0) {
    throw new BridgeFault("INVALID_REQUEST", "Opacity must be 0–1, offsets finite, and scale positive");
  }
  state = next;
  try {
    await request("add-image", [absolutePath]);
    await request("switch-image", absolutePath);
    for (const [key, value] of Object.entries({ x: next.offsetX, y: next.offsetY, sx: next.scale, sy: next.scale, opacity: next.visible ? Math.round(next.opacity * 100) : 0 })) {
      await request("set-image-data", key, value);
    }
    await request("refresh");
    const current = await currentImage();
    if (current?.path !== absolutePath || current.missing) throw new Error("Creator did not confirm the requested reference image");
    return payload(current);
  } catch (error) {
    return payload(null, `Reference image registered locally; viewport display unavailable: ${String(error)}`);
  }
}

export async function clearReferenceImage(): Promise<JsonValue> {
  try {
    const current = await currentImage();
    // Deselect our image; do not remove the user's shared reference-image library.
    if (state && current?.path === state.absolutePath) { await request("switch-image", ""); await request("refresh"); }
    state = null;
    return payload(await currentImage());
  } catch (error) {
    state = null;
    return payload(null, `Local reference state cleared; editor deselection could not be confirmed: ${String(error)}`);
  }
}

/** Called on document close/unload. Never remove another document's reference image. */
export function resetReferenceImageState(): void { state = null; }

export async function getReferenceImage(): Promise<JsonValue> {
  let current: EditorImage | null;
  try { current = await currentImage(); }
  catch (error) {
    const result = payload(null, `Official reference-image extension unavailable: ${String(error)}`) as Record<string, JsonValue>;
    return state ? { ...result, ...await readImage(state.absolutePath) } : result;
  }
  const result = payload(current) as Record<string, JsonValue>;
  return current?.path ? { ...result, ...await readImage(current.path), imageSource: "reference-original" } : result;
}
