import { chmod, mkdir, readFile, rename, unlink, writeFile } from "node:fs/promises";
import { dirname, resolve } from "node:path";
import { defaultConnectionFilePath } from "./project-paths.js";
import { ConnectionInfoSchema, type ConnectionInfo } from "./protocol.js";

export async function readConnectionFile(path?: string): Promise<ConnectionInfo> {
  const connectionPath = resolve(path ?? defaultConnectionFilePath());
  const raw: unknown = JSON.parse(await readFile(connectionPath, "utf8"));
  return ConnectionInfoSchema.parse(raw);
}

export async function writeConnectionFile(path: string, connection: ConnectionInfo): Promise<void> {
  const connectionPath = resolve(path);
  const validated = ConnectionInfoSchema.parse(connection);
  const temporaryPath = `${connectionPath}.${process.pid}.${Date.now()}.tmp`;
  await mkdir(dirname(connectionPath), { recursive: true });
  try {
    await writeFile(temporaryPath, `${JSON.stringify(validated, null, 2)}\n`, { mode: 0o600 });
    await chmod(temporaryPath, 0o600);
    await rename(temporaryPath, connectionPath);
    await chmod(connectionPath, 0o600);
  } catch (error) {
    await unlink(temporaryPath).catch(() => undefined);
    throw error;
  }
}
