  async previewProbe(): Promise<PreviewStatus> {
    if (Editor.App.version !== "3.8.8") {
      return { available: false, running: false, stopSupported: false, message: `Preview adapter requires Creator 3.8.8, received ${Editor.App.version}` };
    }
    try {
      await Editor.Message.request("preview", "ready");
      const status = await this.previewStatus();
      return { ...status, available: true, stopSupported: false, message: "Creator 3.8.8 preview IPC is available; this version exposes no official stop message." };
    } catch (error) {
      return { available: false, running: false, stopSupported: false, message: error instanceof Error ? error.message : String(error) };
    }
  }

  async hasUnsavedChanges(): Promise<boolean> {
    return Boolean(await Editor.Message.request("scene", "query-dirty"));
  }

  async previewStart(options?: { target?: string }): Promise<PreviewStatus> {
    await this.getTree();
    const mode = previewModes.previewModeForStart(options?.target);
    if (mode) await previewModes.setPreviewMode(mode);
    const effectiveMode = mode ?? (await previewModes.getPreviewMode()).mode;
    if (effectiveMode === "gameView") {
      await Editor.Message.request("scene", "editor-preview-set-play", true);
    } else {
      await Editor.Message.request("preview", "open-terminal");
    }
    previewStartedAt = new Date().toISOString();
    return this.previewStatus();
  }

