  async previewStatus(): Promise<PreviewStatus> {
    const urlValue = await Editor.Message.request("preview", "query-preview-url").catch(() => undefined);
    const connectionValue = await Editor.Message.request("preview", "query-connect-num").catch(() => 0);
    const url = typeof urlValue === "string" ? urlValue : undefined;
    const connections = typeof connectionValue === "number" ? connectionValue : 0;
    return {
      available: Editor.App.version === "3.8.8",
      running: connections > 0 || Boolean(previewStartedAt),
      ...(url ? { url } : {}),
      connections,
      ...(previewStartedAt ? { startedAt: previewStartedAt } : {}),
      sessionId,
      stopSupported: false,
    };
  }

