import type { BridgeError } from "./protocol.js";

/** Whether a Bridge failure is safe to retry without changing the request. */
export function bridgeErrorRetryable(code: BridgeError["code"]): boolean {
  return code === "TIMEOUT" || code === "INTERNAL_ERROR";
}

/** Map Bridge protocol failures to the local HTTP API without losing their code. */
export function bridgeErrorHttpStatus(code: BridgeError["code"]): number {
  if (code === "REVISION_CONFLICT" || code === "HASH_CONFLICT" || code === "ALREADY_EXISTS" || code === "NO_UNDO") return 409;
  if (code === "NOT_FOUND") return 404;
  if (code === "UNAUTHORIZED" || code === "CAPABILITY_DENIED") return 403;
  if (code === "UNSUPPORTED" || code === "PROTOCOL_MISMATCH") return 501;
  if (code === "TIMEOUT") return 504;
  if (code === "INTERNAL_ERROR") return 500;
  return 400;
}

/** Bridge 领域错误，携带协议错误码与可选详情。 */
export class BridgeFault extends Error {
  readonly bridgeError: BridgeError;

  /** 使用错误码、消息与可选详情构造故障。 */
  constructor(
    public readonly code: BridgeError["code"],
    message: string,
    public readonly details?: BridgeError["details"],
  ) {
    super(message);
    this.name = "BridgeFault";
    this.bridgeError = { code, message, ...(details === undefined ? {} : { details }) };
  }
}


/** A validated, matching protocol response, distinct from transport loss. It does not prove rollback or effect completion. */
export class RemoteBridgeFault extends BridgeFault {
  constructor(code:BridgeError["code"], message:string, details:BridgeError["details"],
    public readonly responseId:string, public readonly responseHash:string) {
    super(code,message,details);
    this.name="RemoteBridgeFault";
  }
}
