import { BridgeFault } from "../../mcp/src/errors.js";
import type {
  EditorViewFocusResult,
  EditorViewMode,
  EditorViewResetResult,
  EditorViewStatus,
} from "../../mcp/src/protocol.js";

export type EditorMessageRequest = (channel: string, message: string, ...args: unknown[]) => Promise<unknown>;

function unsupported(capability: string, error: unknown): BridgeFault {
  const detail = error instanceof Error ? error.message : String(error);
  return new BridgeFault("UNSUPPORTED", `Creator Scene View ${capability} is unavailable: ${detail}`);
}

/** Safe wrapper around the public Creator 3.8.8 `scene` contribution messages. */
export class SceneViewController {
  constructor(
    private readonly request: EditorMessageRequest,
    private readonly creatorVersion: string,
  ) {}

  async getStatus(): Promise<EditorViewStatus> {
    let mode: EditorViewMode | null = null;
    let gridVisible: boolean | null = null;
    let modeSupported = false;
    let gridSupported = false;

    try {
      const is2d = await this.request("scene", "query-is2D");
      if (typeof is2d !== "boolean") throw new Error("query-is2D returned a non-boolean value");
      mode = is2d ? "2d" : "3d";
      modeSupported = true;
    } catch {
      // A missing query affects only this capability.
    }

    try {
      const visible = await this.request("scene", "query-is-grid-visible");
      if (typeof visible !== "boolean") throw new Error("query-is-grid-visible returned a non-boolean value");
      gridVisible = visible;
      gridSupported = true;
    } catch {
      // A missing query affects only this capability.
    }

    const cameraSupported = this.creatorVersion === "3.8.8";
    return {
      mode,
      gridVisible,
      supported: {
        mode: modeSupported,
        grid: gridSupported,
        focus: cameraSupported,
        reset: cameraSupported,
      },
    };
  }

  async focus(nodeUuids: string[]): Promise<EditorViewFocusResult> {
    if (this.creatorVersion !== "3.8.8") throw unsupported("focus", `Creator ${this.creatorVersion}`);
    for (const uuid of nodeUuids) {
      let node: unknown;
      try {
        node = await this.request("scene", "query-node", uuid);
      } catch {
        throw new BridgeFault("NOT_FOUND", `Scene node not found: ${uuid}`);
      }
      if (!node) throw new BridgeFault("NOT_FOUND", `Scene node not found: ${uuid}`);
    }
    try {
      await this.request("scene", "focus-camera", nodeUuids);
    } catch (error) {
      throw unsupported("focus", error);
    }
    return { focusedNodeUuids: [...nodeUuids] };
  }

  async setMode(mode: EditorViewMode): Promise<EditorViewStatus> {
    try {
      await this.request("scene", "change-is2D", mode === "2d");
    } catch (error) {
      throw unsupported("mode control", error);
    }
    const status = await this.getStatus();
    if (!status.supported.mode) throw unsupported("mode read-back", "query-is2D is unavailable");
    if (status.mode !== mode) {
      throw new BridgeFault("INTERNAL_ERROR", `Scene View mode read-back mismatch: expected ${mode}, received ${status.mode}`);
    }
    return status;
  }

  async setGrid(visible: boolean): Promise<EditorViewStatus> {
    try {
      await this.request("scene", "set-grid-visible", visible);
    } catch (error) {
      throw unsupported("grid control", error);
    }
    const status = await this.getStatus();
    if (!status.supported.grid) throw unsupported("grid read-back", "query-is-grid-visible is unavailable");
    if (status.gridVisible !== visible) {
      throw new BridgeFault("INTERNAL_ERROR", `Scene View grid read-back mismatch: expected ${visible}, received ${status.gridVisible}`);
    }
    return status;
  }

  async reset(): Promise<EditorViewResetResult> {
    if (this.creatorVersion !== "3.8.8") throw unsupported("reset", `Creator ${this.creatorVersion}`);
    try {
      await this.request("scene", "focus-camera", []);
    } catch (error) {
      throw unsupported("reset", error);
    }
    return { reset: true };
  }
}
