import type { SceneAdapter, PatchResult, UndoResult } from "./scene-adapter.js";
import type { ScenePatch, SceneSnapshot } from "./protocol.js";

/** 场景/Prefab 文档事务入口，统一转发到适配器。 */
export class DocumentService {
  /** 绑定底层场景适配器。 */
  constructor(private readonly adapter: SceneAdapter) {}

  /** 读取当前文档树快照。 */
  getTree(options?: { fresh?: boolean; acknowledgeRecovery?: boolean }): Promise<SceneSnapshot> { return this.adapter.getTree(options); }
  /** 应用修订号守卫的补丁事务。 */
  applyPatch(patch: ScenePatch): Promise<PatchResult> { return this.adapter.applyPatch(patch); }
  /** 撤销最近一次 MCP 写入。 */
  undoLastWrite(): Promise<UndoResult> { return this.adapter.undoLastWrite(); }
}
