import { BridgeFault } from "../../mcp/src/errors.js";
import type { PreviewMode, PreviewModeInfo } from "../../mcp/src/protocol.js";

declare const Editor: {
  App: { version: string };
  Message: {
    request(channel: string, message: string, ...args: unknown[]): Promise<unknown>;
    send(channel: string, message: string, ...args: unknown[]): void;
  };
  Profile: {
    getConfig(packageName: string, path: string, scope?: string): Promise<unknown>;
    setConfig(packageName: string, path: string, value: unknown, scope?: string): Promise<void>;
  };
};

const PREVIEW_MODES: readonly PreviewMode[] = ["browser", "gameView", "simulator"];
const PROFILE_PLATFORM_KEY = "preview.current.platform";

let currentMode: PreviewMode = "browser";

function requireCreator388(): void {
  if (Editor.App.version !== "3.8.8") {
    throw new BridgeFault(
      "UNSUPPORTED",
      `Preview mode APIs require Creator 3.8.8, received ${Editor.App.version}`,
    );
  }
}

export function isPreviewMode(value: string): value is PreviewMode {
  return (PREVIEW_MODES as readonly string[]).includes(value);
}

function normalizePreviewMode(value: unknown): PreviewMode | undefined {
  if (typeof value !== "string") return undefined;
  if (value === "game-view") return "gameView";
  return isPreviewMode(value) ? value : undefined;
}

async function readProfileMode(): Promise<PreviewMode | undefined> {
  try {
    return normalizePreviewMode(await Editor.Profile.getConfig("preview", PROFILE_PLATFORM_KEY, "local"));
  } catch {
    return undefined;
  }
}

async function queryPreviewUrl(): Promise<string | undefined> {
  try {
    const urlValue = await Editor.Message.request("preview", "query-preview-url");
    return typeof urlValue === "string" && urlValue.length > 0 ? urlValue : undefined;
  } catch {
    return undefined;
  }
}

/** Preview mode helpers for Creator 3.8.8 toolbar parity (browser / gameView / simulator). */
export async function getPreviewMode(): Promise<PreviewModeInfo> {
  const profileMode = await readProfileMode();
  if (profileMode) currentMode = profileMode;

  const url = await queryPreviewUrl();
  const message = profileMode
    ? "Mode read from preview profile (preview.current.platform)"
    : "Mode tracked in-process; preview profile IPC unavailable";

  return {
    mode: currentMode,
    ...(url ? { url } : {}),
    message,
  };
}

export async function setPreviewMode(mode: PreviewMode): Promise<PreviewModeInfo> {
  requireCreator388();
  currentMode = mode;

  let ipcApplied = false;
  const ipcNotes: string[] = [];

  try {
    await Editor.Profile.setConfig("preview", PROFILE_PLATFORM_KEY, mode, "local");
    ipcApplied = true;
    ipcNotes.push("Profile.setConfig(preview.current.platform)");
  } catch (error) {
    ipcNotes.push(`Profile.setConfig failed: ${error instanceof Error ? error.message : String(error)}`);
  }

  try {
    Editor.Message.send("preview", "change-platform", mode);
    ipcApplied = true;
    ipcNotes.push("preview:change-platform");
  } catch (error) {
    ipcNotes.push(`preview:change-platform failed: ${error instanceof Error ? error.message : String(error)}`);
  }

  const url = await queryPreviewUrl();
  const message = ipcApplied
    ? `Preview mode set to ${mode} via Creator preview IPC (${ipcNotes.join(", ")})`
    : `Preview mode set to ${mode} in-process only (${ipcNotes.join("; ")})`;

  return {
    mode: currentMode,
    ...(url ? { url } : {}),
    message,
  };
}

export function previewModeForStart(target?: string): PreviewMode | undefined {
  if (!target) return undefined;
  return normalizePreviewMode(target);
}
