  /** 按能力档位拒绝未授权的写操作或破坏性操作。 */
  private assertCapability(request: BridgeRequest): void {
    if (this.capabilityProfile === "read-only" && !READ_METHODS.has(request.method)) {
      throw new BridgeFault("CAPABILITY_DENIED", `${request.method} is disabled by the read-only capability profile`);
    }
    if ((request.method === "script.executeScene" || request.method === "script.executeEditor") && this.capabilityProfile !== "full-control") {
      throw new BridgeFault("CAPABILITY_DENIED", `${request.method} requires the full-control capability profile`);
    }
    const operations = request.method === "scene.applyPatch" || request.method === "prefab.applyPatch"
      ? (request.params as { operations?: Array<{ op?: string }> } | undefined)?.operations
      : undefined;
    const destructive = request.method === "asset.delete" || operations?.some((operation) => operation.op === "removeNode");
    if (destructive && this.capabilityProfile !== "full-control") {
      throw new BridgeFault("CAPABILITY_DENIED", `${request.method} requires the full-control capability profile`);
    }
  }

  /** 取得并绑定 P2 适配器方法，缺失时抛出 UNSUPPORTED。 */
  private p2<K extends keyof P2Adapter>(name: K): NonNullable<P2Adapter[K]> {
    const capability = this.adapter[name];
    if (typeof capability !== "function") throw new BridgeFault("UNSUPPORTED", `${name} is unavailable`);
    return capability.bind(this.adapter) as NonNullable<P2Adapter[K]>;
  }

  private optionalP2<K extends keyof P2Adapter>(name: K): NonNullable<P2Adapter[K]> {
    return this.p2(name);
  }

