  /** 记录一次方法调用的审计摘要（最多保留 100 条）。 */
  private recordAudit(method: BridgeRequest["method"], started: number, response: BridgeResponse): void {
    const result = response.ok && typeof response.result === "object" && response.result !== null
      ? response.result as Record<string, JsonValue>
      : undefined;
    const after = result?.after && typeof result.after === "object" && !Array.isArray(result.after)
      ? result.after as Record<string, JsonValue>
      : undefined;
    const revision = typeof result?.revision === "string"
      ? result.revision
      : typeof after?.revision === "string" ? after.revision : undefined;
    const hash = typeof result?.hash === "string" ? result.hash : undefined;
    const event: AuditEvent = {
      id: randomUUID(),
      method,
      startedAt: new Date(Date.now() - (performance.now() - started)).toISOString(),
      durationMs: Math.round(performance.now() - started),
      ok: response.ok,
      summary: response.ok ? "completed" : response.error.message,
      ...(response.ok ? {} : { errorCode: response.error.code }),
      ...(revision ? { revision } : {}),
      ...(hash ? { hash } : {}),
    };
    this.audit.unshift(event);
    if (this.audit.length > 100) this.audit.length = 100;
  }

  /** 构造统一的失败响应。 */
  private failure(
    id: string,
    code: BridgeError["code"],
    message: string,
    details?: JsonValue,
  ): BridgeResponse {
    const error: BridgeError = details === undefined ? { code, message } : { code, message, details };
    return { id, ok: false, error };
  }
