import { BridgeFault } from "../../mcp/src/errors.js";
import type { SceneSnapshot } from "../../mcp/src/protocol.js";

type EditorRequest = (channel: string, message: string, ...args: unknown[]) => Promise<unknown>;

export async function resolveCurrentDocument(
  tree: SceneSnapshot,
  request: EditorRequest,
): Promise<SceneSnapshot> {
  const uuid = await request("scene", "query-current-scene");
  if (typeof uuid !== "string" || !uuid) return tree;
  const asset = await request("asset-db", "query-asset-info", uuid) as { url?: unknown } | null;
  return typeof asset?.url === "string" && asset.url.startsWith("db://")
    ? { ...tree, sceneUrl: asset.url }
    : tree;
}

export function assertDocumentCanAutoSave(tree: Pick<SceneSnapshot, "sceneUrl">): void {
  if (!tree.sceneUrl.startsWith("db://")) {
    throw new BridgeFault(
      "REVISION_CONFLICT",
      "Current scene has no asset URL. Create or open a scene asset before using tools that save changes",
    );
  }
}

/** Save one patch, restoring and saving its inverse if persistence fails. */
export async function savePatchOrRestore(
  save: () => Promise<unknown>,
  undo: () => Promise<{ restored: SceneSnapshot }>,
  beforeRevision: string,
  requireRecoveryRead?: () => Promise<unknown> | unknown,
  assertCurrent?: () => Promise<unknown> | unknown,
): Promise<void> {
  try {
    await assertCurrent?.();
    await save();
  } catch (original) {
    try {
      const { restored } = await undo();
      if (restored.revision !== beforeRevision) {
        throw new Error("Restored scene does not match the pre-write revision");
      }
      await save();
    } catch (recovery) {
      await requireRecoveryRead?.();
      throw new BridgeFault("REVISION_CONFLICT", "Save failed and restoration could not be verified; read the current scene before another write", {
        originalError: original instanceof Error ? original.message : String(original),
        recoveryError: recovery instanceof Error ? recovery.message : String(recovery),
      });
    }
    throw original;
  }
}
